INSERT INTO "battle" ("id", "slug", "author_id", "title", "context", "category_id", "tags", "deadline", "created_at") VALUES
  ('seed_tb_1', 'tvjASde5', (SELECT id FROM "user" WHERE handle = 'brightfern_12'), 'Opening line for my sister''s wedding toast?', 'I''m maid of honor. Crowd of 150, mostly family. I get nervous.', 'other', '{}'::jsonb, now() + interval '118 hours', now() - interval '101 minutes'),
  ('seed_tb_2', 'tyNdHocf', (SELECT id FROM "user" WHERE handle = 'quietharbor_7'), 'Best man toast: how do I open?', 'Groom is my college roommate. His grandma will be front row.', 'other', '{}'::jsonb, now() + interval '111 hours', now() - interval '433 minutes'),
  ('seed_tb_3', 'teqfLCd5', (SELECT id FROM "user" WHERE handle = 'mossylark_31'), 'Toast for my parents'' 40th anniversary', 'Short speech at dinner, about 30 people.', 'other', '{}'::jsonb, now() + interval '91 hours', now() - interval '233 minutes'),
  ('seed_tb_4', 'tRRNdMNA', (SELECT id FROM "user" WHERE handle = 'velvetotter_5'), 'Which first line for my dating profile?', 'Women 28-35, I''m 31 and new to the apps.', 'other', '{}'::jsonb, now() + interval '87 hours', now() - interval '231 minutes'),
  ('seed_tb_5', 'tcL7itBj', (SELECT id FROM "user" WHERE handle = 'saltpine_44'), 'Which dating profile bio sounds better?', 'I''m 27, nurse, work nights. Want something real.', 'other', '{}'::jsonb, now() + interval '118 hours', now() - interval '125 minutes'),
  ('seed_tb_6', 'tMuL5Umg', (SELECT id FROM "user" WHERE handle = 'amberwren_19'), 'Profile prompt: "My most irrational fear"', 'Trying to be funny without being weird.', 'other', '{}'::jsonb, now() + interval '96 hours', now() - interval '386 minutes'),
  ('seed_tb_7', 'tgLWeMdQ', (SELECT id FROM "user" WHERE handle = 'ruststar_62'), 'Profile prompt: "We''ll get along if..."', 'Men 30-40. I''m a single mom of a 6 year old.', 'other', '{}'::jsonb, now() + interval '97 hours', now() - interval '513 minutes'),
  ('seed_tb_8', 'tUKC2vEN', (SELECT id FROM "user" WHERE handle = 'cloverdune_8'), 'How do I open a message to a match?', 'Her profile says she just got back from Portugal.', 'other', '{}'::jsonb, now() + interval '113 hours', now() - interval '375 minutes'),
  ('seed_tb_9', 'tuq3mV2q', (SELECT id FROM "user" WHERE handle = 'hazelridge_23'), 'Third date idea', 'We''ve done drinks and dinner. She''s into art.', 'other', '{}'::jsonb, now() + interval '89 hours', now() - interval '593 minutes'),
  ('seed_tb_10', 'tuJG9wXD', (SELECT id FROM "user" WHERE handle = 'lunafield_9'), 'Should I say "I love you" first?', 'Together 4 months. I''m pretty sure he feels it too.', 'other', '{}'::jsonb, now() + interval '102 hours', now() - interval '79 minutes'),
  ('seed_tb_11', 'thHBkZwj', (SELECT id FROM "user" WHERE handle = 'tidecove_51'), 'How to tell my partner I need more alone time?', 'We moved in together 2 months ago.', 'other', '{}'::jsonb, now() + interval '115 hours', now() - interval '436 minutes'),
  ('seed_tb_12', 'tcTeZLM3', (SELECT id FROM "user" WHERE handle = 'sparrowkey_3'), 'Meeting his parents for the first time. Bring what?', 'Dinner at their house, they''re pretty traditional.', 'other', '{}'::jsonb, now() + interval '104 hours', now() - interval '353 minutes'),
  ('seed_tb_13', 'tVxPGN4E', (SELECT id FROM "user" WHERE handle = 'ivoryglen_77'), 'Ex wants to be friends. What do I say?', 'Broke up 3 months ago, it was mutual.', 'other', '{}'::jsonb, now() + interval '88 hours', now() - interval '100 minutes'),
  ('seed_tb_14', 'tsFVTedX', (SELECT id FROM "user" WHERE handle = 'copperlake_14'), 'How do I end a first date that went nowhere?', 'Nice guy, zero chemistry. Don''t want to ghost.', 'other', '{}'::jsonb, now() + interval '103 hours', now() - interval '596 minutes'),
  ('seed_tb_15', 'tU5DtWz9', (SELECT id FROM "user" WHERE handle = 'northbirch_28'), 'Elevator pitch for networking events', 'I''m a freelance UX designer.', 'other', '{}'::jsonb, now() + interval '106 hours', now() - interval '28 minutes'),
