INSERT INTO "option" ("id", "battle_id", "side", "label", "description")
SELECT v."id", v."battle_id", v."side"::side, v."label", v."description" FROM (VALUES
  ('seed_to_1_a', 'seed_tb_1', 'A', '"I''ve been her sister for 29 years and her favorite for most of them."', 'Start with a laugh to calm my nerves and the room.'),
  ('seed_to_1_b', 'seed_tb_1', 'B', '"The first time she talked about Marcus, she didn''t stop smiling for an hour."', 'Start warm and go straight to the love story.'),
  ('seed_to_2_a', 'seed_tb_2', 'A', '"For those who don''t know me, I''m the guy who taught Dan how to do laundry."', 'Light roast that''s safe for grandma.'),
  ('seed_to_2_b', 'seed_tb_2', 'B', '"Ten years ago Dan told me he''d met the one. He was right, which is a first."', 'Sweet with a small joke at the end.'),
  ('seed_to_3_a', 'seed_tb_3', 'A', '"Forty years, three kids, and Dad still lets Mom win at cards."', 'Funny and specific.'),
  ('seed_to_3_b', 'seed_tb_3', 'B', '"Everything I know about love, I learned watching you two at the kitchen table."', 'Heartfelt from the first line.'),
  ('seed_to_4_a', 'seed_tb_4', 'A', '"I will judge you, kindly, on your coffee order."', 'Playful and gives an easy opener.'),
  ('seed_to_4_b', 'seed_tb_4', 'B', '"Looking for someone to try every taco spot in the city with."', 'Clear about what a date with me looks like.'),
  ('seed_to_5_a', 'seed_tb_5', 'A', '"Night-shift nurse. I''ll keep you alive and make you laugh."', 'Short, confident, a little funny.'),
  ('seed_to_5_b', 'seed_tb_5', 'B', '"I spend my nights helping strangers. Looking for someone to spend my days off with."', 'Softer and says I want something serious.'),
  ('seed_to_6_a', 'seed_tb_6', 'A', '"That the waiter will say ''enjoy your meal'' and I''ll say ''you too.''"', 'Relatable awkward humor.'),
  ('seed_to_6_b', 'seed_tb_6', 'B', '"Geese. They know what they did."', 'Short, absurd, gets replies.'),
  ('seed_to_7_a', 'seed_tb_7', 'A', '"...you''re cool with a 6 year old asking you about dinosaurs."', 'Mentions my kid upfront in a light way.'),
  ('seed_to_7_b', 'seed_tb_7', 'B', '"...you think Sunday mornings are for pancakes and no plans."', 'Keeps it about lifestyle, kid comes up later.'),
  ('seed_to_8_a', 'seed_tb_8', 'A', '"Okay, Portugal: best pastel de nata you had, and was it worth the flight?"', 'Specific question about her trip.'),
  ('seed_to_8_b', 'seed_tb_8', 'B', '"Hi! You have a great smile. How''s your week going?"', 'Simple and friendly.'),
  ('seed_to_9_a', 'seed_tb_9', 'A', 'Pottery class together', 'Hands-on, a little messy, lots to laugh about.'),
  ('seed_to_9_b', 'seed_tb_9', 'B', 'Gallery walk then a wine bar', 'Lets us talk, still feels special.'),
  ('seed_to_10_a', 'seed_tb_10', 'A', 'Say it now', 'Life''s short. If you feel it, say it.'),
  ('seed_to_10_b', 'seed_tb_10', 'B', 'Wait for him', 'Let him get there on his own time.'),
  ('seed_to_11_a', 'seed_tb_11', 'A', '"I love living with you. I also need one night a week that''s just mine."', 'Lead with the positive, ask for something specific.'),
  ('seed_to_11_b', 'seed_tb_11', 'B', '"I''ve been feeling a little drained lately and want to talk about space."', 'Open up about the feeling first, then figure it out together.'),
  ('seed_to_12_a', 'seed_tb_12', 'A', 'A bottle of nice wine', 'Classic, easy, grown-up.'),
  ('seed_to_12_b', 'seed_tb_12', 'B', 'Homemade dessert', 'Personal and shows effort.'),
  ('seed_to_13_a', 'seed_tb_13', 'A', '"I''d like that eventually, but I need some time first."', 'Kind, leaves the door open later.'),
  ('seed_to_13_b', 'seed_tb_13', 'B', '"I think we should give each other real space for now."', 'Clear boundary, no mixed signals.'),
  ('seed_to_14_a', 'seed_tb_14', 'A', '"I had a nice time, but I didn''t feel a spark. Wishing you the best."', 'Honest text the same night.'),
  ('seed_to_14_b', 'seed_tb_14', 'B', '"Thanks for tonight!" and let it fade', 'Polite, no big conversation.'),
  ('seed_to_15_a', 'seed_tb_15', 'A', '"I make apps so easy your grandma could use them."', 'Simple, memorable, a bit playful.'),
  ('seed_to_15_b', 'seed_tb_15', 'B', '"I help startups turn confused users into paying customers through better design."', 'Business value first.'),
  ('seed_to_16_a', 'seed_tb_16', 'A', '"Your customers want something fresh with their latte. I bake it at 5am, ten minutes away."', 'Focus on their customers.'),
  ('seed_to_16_b', 'seed_tb_16', 'B', '"Small-batch sourdough pastries, voted best in the neighborhood two years running."', 'Lead with credibility.'),
  ('seed_to_17_a', 'seed_tb_17', 'A', '"How many hours a week does your front desk spend on reschedules?"', 'Start with their pain.'),
  ('seed_to_17_b', 'seed_tb_17', 'B', '"We cut no-shows by 30% for practices like yours. Can I show you how in 2 minutes?"', 'Start with a number.'),
  ('seed_to_18_a', 'seed_tb_18', 'A', '"Burnout is costing your team more than you think."', 'Bold, a little scary.'),
  ('seed_to_18_b', 'seed_tb_18', 'B', '"Quick idea to help your team feel better at work, without adding meetings."', 'Friendly and low-pressure.'),
  ('seed_to_19_a', 'seed_tb_19', 'A', '"I took two years to care for my father. It taught me patience and how to manage a lot at once."', 'Own it and turn it into a strength.'),
  ('seed_to_19_b', 'seed_tb_19', 'B', '"I took time off for family and I''m excited to be back and focused."', 'Short, keep the focus on the future.'),
  ('seed_to_20_a', 'seed_tb_20', 'A', 'Joke about it first', '"Fair warning, I''m fun-sized." Takes the power back.'),
  ('seed_to_20_b', 'seed_tb_20', 'B', 'Don''t mention it at all', 'Confidence is the attractive part. Let it be a non-issue.'),
  ('seed_to_21_a', 'seed_tb_21', 'A', '"I feel a lot better without it."', 'True, simple, ends the question.'),
  ('seed_to_21_b', 'seed_tb_21', 'B', '"I''m sober, it''s been the best year of my life."', 'Open and proud, owns the story.'),
  ('seed_to_22_a', 'seed_tb_22', 'A', 'Theo', 'Short, warm, pairs nicely with Ivy.'),
  ('seed_to_22_b', 'seed_tb_22', 'B', 'Henry', 'Classic and strong. Henry and Ivy Bennett.'),
  ('seed_to_23_a', 'seed_tb_23', 'A', 'Lucia', 'Italian roots, sounds great with Rossi.'),
  ('seed_to_23_b', 'seed_tb_23', 'B', 'Nora', 'Simple and classic, goes with Emma.'),
  ('seed_to_24_a', 'seed_tb_24', 'A', 'June Elizabeth Carter', 'Classic and flows well.'),
  ('seed_to_24_b', 'seed_tb_24', 'B', 'June Margaret Carter', 'After my grandmother, goes by Maggie in the family.'),
  ('seed_to_25_a', 'seed_tb_25', 'A', 'Just one last name', 'Simpler for school, forms and life.'),
  ('seed_to_25_b', 'seed_tb_25', 'B', 'Hyphenated', 'Both families are part of his name.'),
  ('seed_to_26_a', 'seed_tb_26', 'A', 'Startup: $95k + equity, fully remote', 'Exciting and flexible, more risk.'),
  ('seed_to_26_b', 'seed_tb_26', 'B', 'Big company: $120k, office 3 days a week', 'Stable, better pay, longer commute.'),
  ('seed_to_27_a', 'seed_tb_27', 'A', 'Move closer', 'Help with the kids and more time with grandparents.'),
  ('seed_to_27_b', 'seed_tb_27', 'B', 'Stay put', 'Keep our jobs, friends and the school we love.'),
  ('seed_to_28_a', 'seed_tb_28', 'A', 'Buy the condo', 'Build equity, it''s ours.'),
  ('seed_to_28_b', 'seed_tb_28', 'B', 'Keep renting', 'Stay flexible and keep the cash cushion.'),
  ('seed_to_29_a', 'seed_tb_29', 'A', 'Go for it', 'Two years of hard work for a career I''ll love.'),
  ('seed_to_29_b', 'seed_tb_29', 'B', 'Wait a year and save', 'Less stress, start with money in the bank.'),
  ('seed_to_30_a', 'seed_tb_30', 'A', 'Tell her now, gently', 'She deserves to know, even if it''s awkward.'),
  ('seed_to_30_b', 'seed_tb_30', 'B', 'Get more proof first', 'Make sure before blowing up her relationship.')
) AS v("id", "battle_id", "side", "label", "description")
WHERE EXISTS (SELECT 1 FROM "battle" b WHERE b."id" = v."battle_id")
ON CONFLICT DO NOTHING;
